<script setup lang="ts">
import {computed,nextTick,onMounted,reactive,ref,watch} from 'vue'
import {scheduleApi} from '../schedules'
import {dismissAfterFourSeconds} from '../temporary-message'
const emit=defineEmits<{saving:[value:boolean]}>()
const parents=ref<any[]>([]),busy=ref(false),loading=ref(false),error=ref(''),message=ref(''),dialogError=ref(''),filter=ref('')
const dialog=ref<HTMLDialogElement|null>(null),mode=ref('create'),selected=ref<any>(null),student=ref<any>(null),matches=ref<any[]>([]),query=ref(''),searching=ref(false),verified=ref(false)
const form=reactive({full_name:'',email:'',phone_number:'',login_id:'',password:'',relationship:'Guardian'})
dismissAfterFourSeconds(message)
watch(query,()=>{student.value=null;matches.value=[];if(mode.value==='create')form.login_id=''})
const visible=computed(()=>parents.value.filter(p=>(p.full_name+' '+p.login_id+' '+p.children.map((c:any)=>c.full_name+' '+c.login_id).join(' ')).toLowerCase().includes(filter.value.toLowerCase())))
const title=computed(()=>mode.value==='create'?'Create parent':mode.value==='children'?'Manage linked children':'Edit parent contact details')
async function load(){loading.value=true;error.value='';try{parents.value=(await scheduleApi('admin/parents')).parents;if(selected.value)selected.value=parents.value.find(p=>p.id===selected.value.id)??null}catch(e){error.value=e instanceof Error?e.message:'Unable to load parents.'}finally{loading.value=false}}
async function open(action:string,p:any=null){mode.value=action;selected.value=p;student.value=null;matches.value=[];query.value='';verified.value=false;dialogError.value='';Object.assign(form,{full_name:p?.full_name??'',email:p?.email??'',phone_number:p?.phone_number??'',login_id:'',password:'',relationship:'Guardian'});await nextTick();dialog.value?.showModal()}
function close(){if(busy.value)return;dialog.value?.close();form.password='';dialogError.value=''}
async function find(){searching.value=true;dialogError.value='';try{matches.value=(await scheduleApi('admin/parents/students?search='+encodeURIComponent(query.value))).students}catch(e){dialogError.value=e instanceof Error?e.message:'Unable to find students.'}finally{searching.value=false}}
async function choose(s:any){student.value=s;matches.value=[];dialogError.value='';if(mode.value==='create'){searching.value=true;try{form.login_id=(await scheduleApi('admin/parents/suggest-login?student_id='+s.id)).login_id}catch(e){dialogError.value=e instanceof Error?e.message:'Unable to suggest login.'}finally{searching.value=false}}}
async function run(action:()=>Promise<any>,keepOpen=false){if(busy.value)return;busy.value=true;emit('saving',true);dialogError.value='';try{const result=await action();message.value=result.message;await load();if(!keepOpen)dialog.value?.close();form.password='';student.value=null}catch(e){dialogError.value=e instanceof Error?e.message:'Unable to save parent details.'}finally{busy.value=false;emit('saving',false)}}
async function save(){if(mode.value==='profile')return run(()=>scheduleApi('admin/parents/'+selected.value.id+'/profile','PUT',{...form}));if(!student.value||!verified.value)return;const payload={...form,student_id:student.value.id,identity_verified:verified.value};await run(()=>scheduleApi(mode.value==='create'?'admin/parents':'admin/parents/'+selected.value.id+'/children','POST',payload),mode.value==='children')}
async function linkStatus(link:any){await run(()=>scheduleApi('admin/parents/'+selected.value.id+'/children/'+link.student_user_id,'PUT',{relationship:link.relationship,is_active:!link.is_active,version:link.version,identity_verified:verified.value}),true)}
const confirmStatus=ref(0)
async function status(p:any){busy.value=true;emit('saving',true);error.value='';try{message.value=(await scheduleApi('admin/parents/'+p.id+'/status','PUT',{is_active:!p.is_active})).message;confirmStatus.value=0;await load()}catch(e){error.value=e instanceof Error?e.message:'Unable to update account.'}finally{busy.value=false;emit('saving',false)}}
onMounted(load)
</script>
<template><section class="card parent-accounts"><div class="heading"><div><p class="eyebrow">PARENTS & GUARDIANS</p><h2>Parent list</h2></div><div class="heading-actions"><button type="button" :disabled="busy||loading" @click="open('create')">Create parent</button><button type="button" class="secondary" :disabled="busy||loading" @click="load">Refresh parents</button></div></div><p class="muted">Verify guardians through school records before linking children. Parent logins use a P prefix; verified database links control access.</p><label class="parent-search">Find a parent or child<input v-model="filter" type="search" placeholder="Name, parent login or student ID"></label><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="message" class="success" role="status">{{message}}</p><p v-if="loading" role="status">Loading parent accounts…</p><p v-else-if="!visible.length" class="muted">No matching parent accounts.</p><article v-for="p in visible" :key="p.id" class="parent-row"><div><h3>{{p.full_name}}</h3><p>{{p.login_id}} · {{p.is_active?'Enabled':'Disabled'}}<span v-if="p.must_change_password"> · Initial password change required</span></p><p class="muted">{{p.children.filter((c:any)=>c.is_active).map((c:any)=>c.full_name+' ('+c.login_id+')').join(' · ')||'No active child links'}}</p></div><div class="row-actions"><button type="button" class="secondary" :disabled="busy" @click="open('children',p)">Linked children</button><button type="button" class="secondary" :disabled="busy" @click="open('profile',p)">Edit contact</button><template v-if="confirmStatus===p.id"><button type="button" :disabled="busy" @click="status(p)">Confirm disable</button><button type="button" class="secondary" @click="confirmStatus=0">Cancel</button></template><button v-else type="button" class="secondary" :disabled="busy" @click="p.is_active?confirmStatus=p.id:status(p)">{{p.is_active?'Disable':'Enable'}}</button></div></article>
<dialog ref="dialog" class="account-create-dialog parent-dialog" aria-labelledby="parent-dialog-title" @cancel.prevent="close"><div class="heading"><h2 id="parent-dialog-title">{{title}}</h2><button type="button" class="secondary" :disabled="busy" @click="close">Close</button></div><p v-if="selected" class="muted">{{selected.full_name}} · {{selected.login_id}}</p><p v-if="dialogError" class="error" role="alert">{{dialogError}}</p>
<form @submit.prevent="save"><fieldset :disabled="busy"><template v-if="mode!=='children'"><label>Parent / guardian name<input v-model="form.full_name" required maxlength="150" autocomplete="name"></label><div class="fields"><label>Email<input v-model="form.email" type="email" maxlength="254" autocomplete="email"></label><label>Phone<input v-model="form.phone_number" type="tel" maxlength="30" autocomplete="tel"></label></div><p class="hint">Enter at least one contact method. School staff share credentials privately.</p></template>
<template v-if="mode!=='profile'"><label class="verification"><input v-model="verified" type="checkbox" required>I verified this guardian’s authority through school records and reviewed the child’s identity.</label><div v-if="mode==='children'&&selected" class="existing-links"><h3>Current links</h3><article v-for="link in selected.children" :key="link.student_user_id"><div><strong>{{link.full_name}}</strong><p>{{link.login_id}} · {{link.relationship}} · {{link.is_active?'Linked':'Removed'}}</p></div><button type="button" class="secondary" :disabled="!verified||busy" @click="linkStatus(link)">{{link.is_active?'Remove link':'Restore link'}}</button></article></div><h3>{{mode==='children'?'Link another child':'Choose the child'}}</h3><div class="student-search"><label>Student ID or name<input v-model="query" type="search" minlength="2" maxlength="100" placeholder="Enter at least 2 characters" @keydown.enter.prevent="find"></label><button type="button" class="secondary" :disabled="query.trim().length<2||searching" @click="find">{{searching?'Finding…':'Find student'}}</button></div><ul v-if="matches.length" class="matches"><li v-for="s in matches" :key="s.id"><button type="button" class="secondary" @click="choose(s)">{{s.full_name}} · {{s.login_id}} · {{s.class_label}}</button></li></ul><p v-else-if="query.trim().length>=2&&!student&&!searching" class="hint">Use Find student, then select the matching record.</p><p v-if="student" class="chosen" role="status">Selected: <strong>{{student.full_name}}</strong> · {{student.login_id}} · {{student.class_label}}</p><label>Relationship<select v-model="form.relationship"><option>Father</option><option>Mother</option><option>Guardian</option><option>Other</option></select></label></template>
<template v-if="mode==='create'"><label>Parent login ID<input v-model="form.login_id" required maxlength="50" pattern="P[A-Za-z0-9_-]+" autocomplete="off"></label><p class="hint">Suggested from the first child’s student ID. Add a suffix for another guardian. This login stays the same if more children are linked.</p><label>Initial password<input v-model="form.password" type="password" required minlength="12" maxlength="72" autocomplete="new-password"></label><p class="hint">At least 12 characters, maximum 72 UTF-8 bytes. The parent must change it at first login.</p></template><div class="popup-actions"><button :disabled="searching||(mode!=='profile'&&(!student||!verified))">{{busy?'Saving…':mode==='create'?'Create parent':mode==='children'?'Link selected child':'Save contact details'}}</button><button type="button" class="secondary" @click="close">Cancel</button></div></fieldset></form></dialog></section></template>
<style scoped>
.heading h2{margin:0}.parent-search{margin:16px 0}.parent-search input{display:block;margin-top:6px}.parent-row{display:flex;align-items:center;justify-content:space-between;gap:16px;border-top:1px solid #dce6df;padding:14px 0}.parent-row h3{font-size:15px;margin:0}.parent-row p{font-size:12px;margin:5px 0;line-height:1.5}.row-actions{display:flex;gap:8px;flex-wrap:wrap}.row-actions button{font-size:12px;padding:9px 12px;min-height:44px}.parent-dialog{width:min(640px,calc(100vw - 24px))!important}.parent-dialog fieldset{border:0;padding:0;min-width:0}.parent-dialog label{margin:14px 0 6px;font-size:13px}.parent-dialog input,.parent-dialog select{display:block;margin-top:6px}.parent-dialog .fields{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:16px 0}.verification{display:flex;align-items:start;gap:10px;background:#eef4f0;padding:12px;border-radius:8px;line-height:1.5}.verification input{width:18px;height:18px;flex-shrink:0;margin:0}.hint{font-size:12px;line-height:1.5;color:#63776b}.student-search{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:12px;align-items:end}.student-search label{min-width:0;margin:0}.student-search input{width:100%;min-width:0}.student-search button{width:auto;white-space:nowrap;margin:0;min-height:44px}.matches{list-style:none;padding:0;display:grid;gap:8px;max-height:220px;overflow:auto}.matches button{width:100%;text-align:left;margin:0;min-height:44px}.chosen{font-size:13px;padding:12px;background:#eef4f0;border-radius:8px;overflow-wrap:anywhere}.existing-links article{display:flex;align-items:center;justify-content:space-between;gap:10px;border-bottom:1px solid #dce6df;padding:10px 0;font-size:13px}.existing-links p{margin:5px 0;font-size:12px}.existing-links button{margin:0;min-height:44px;width:auto;font-size:12px}.popup-actions{margin-top:20px}.parent-dialog h3{font-size:15px;margin:18px 0 10px}@media(max-width:600px){.parent-row{align-items:start;flex-direction:column}.parent-dialog .fields{grid-template-columns:1fr}.student-search{grid-template-columns:minmax(0,1fr)}.student-search button{width:100%}.existing-links article{flex-wrap:wrap}}
</style>
